y:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#e9eedf}.entry-title h3{margin:0;font-size:15px;line-height:1.35}.timeline-entry p{margin:4px 0;color:#5f685f;font-size:14px;line-height:1.58}.timeline-entry small{color:#6b835c;font-size:12px}.timeline-list article.is-major{grid-template-columns:46px minmax(0,1fr);gap:10px}.timeline-list article.is-major .line-mark span{width:13px;height:13px;margin-top:15px;box-shadow:0 0 0 5px #edf2e5}.timeline-list article.is-major .line-mark i{top:28px}.timeline-list article.is-major .timeline-entry{padding-bottom:22px}.timeline-list article.is-major .entry-title{gap:9px;margin-top:3px}.timeline-list article.is-major .entry-icon{width:42px;height:42px;box-shadow:0 6px 13px rgba(64,86,55,.08)}.timeline-list article.is-major .entry-icon img{width:40px;height:40px}.timeline-list article.is-major .entry-title h3{font-size:16px}.empty{margin:0 0 18px;color:#7e847b}.later-paper{display:grid;gap:9px;border-radius:20px;background:rgba(255,253,247,.9);padding:16px;box-shadow:0 11px 24px rgba(20,32,27,.07)}.later-paper label{display:grid;gap:8px;color:#45613f;font-size:15px}.later-paper textarea{min-height:86px;width:100%;border:1px solid rgba(95,127,62,.17);border-radius:13px;background:#fffefa;padding:10px;color:#2e3e32;font:inherit;line-height:1.55;resize:none}.later-paper>div{display:flex;align-items:center;justify-content:space-between;color:#7c8579;font-size:12px}.later-paper button{min-width:76px;min-height:35px;border:0;border-radius:11px;background:#4e714d;color:#fff;font:inherit;cursor:pointer}.later-paper button:disabled{opacity:.55;cursor:wait}.timeline-actions{display:grid;gap:8px;padding:0 12px}.timeline-actions button{min-height:47px;border-radius:999px;border:0;background:#416a50;color:#fff;font:inherit;cursor:pointer}.timeline-actions button+button{border:1px solid rgba(95,127,62,.28);background:rgba(255,253,247,.7);color:#4e673f}.timeline-actions .change-support{min-height:34px;border:0;background:transparent;color:#5d7555;font-size:13px}
.timeline-screen .entry-icon{overflow:hidden}.timeline-screen .entry-icon img{width:30px;height:30px;object-fit:contain;mix-blend-mode:multiply}
</style>
